        writeValue(stream, value.toList())
      }
      is TTWaterMeterInitParam -> {
        stream.write(201)
        writeValue(stream, value.toList())
      }
      is TTElectricMeterInitParam -> {
        stream.write(202)
        writeValue(stream, value.toList())
      }
      is AddCardEvent -> {
        stream.write(203)
        writeValue(stream, value.toList())
      }
      is AddFingerprintEvent -> {
        stream.write(204)
        writeValue(stream, value.toList())
      }
      is AddFaceEvent -> {
        stream.write(205)
        writeValue(stream, value.toList())
      }
      is AddPalmVeinEvent -> {
        stream.write(206)
        writeValue(stream, value.toList())
      }
      else -> super.writeValue(stream, value)
    }
  }
}

val MessagesPigeonMethodCodec = StandardMethodCodec(MessagesPigeonCodec())


